import os
root='/challenge/inhere'
for dp,_,fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn)
        try:
            x=os.listxattr(p)
            if x: print('XATTR',p,x)
        except Exception as e: print('err',p,e)
        st=os.lstat(p)
        data=open(p,'rb').read()
        # expected content
        area=dp.split('/')[-2]; name=fn
        if name=='item00': exp=b'\0'*1033
        elif name=='item01': exp=b'x'*1033
        else:
            line=f"record {area[-2:]}-{name[-2:]}\n".encode()
            exp=(line*(st.st_size//len(line)+1))[:st.st_size]
        if data!=exp:
            print('DIFF',p,len(data))
print('done')
EOF

