import os
root='/challenge/inhere'
n=0
for dp,dns,fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn); n+=1
        st=os.lstat(p)
        if st.st_nlink>1: print('HARDLINK',p,st.st_nlink)
        if not fn.startswith('item'): print('ODDNAME',repr(p))
print('total files',n)
